fn np_sgemv_t(a: &[f32], m: usize, k: usize, x: &[f32]) -> Vec<f32> {
    let mut y = vec![0.0f32; m];
    let r3 = m & 3;
    for r in 0..m {
        let kind = if r < m - r3 { 4 } else if r3 >= 2 && r == m - 2 { 2 } else if r3 >= 1 && r == m - 1 { 1 } else { 4 };
        y[r] = sgemv_t_row32(&a[r * k..(r + 1) * k], x, kind);
    }
    y
}
// one gemv_n 8-x group: even chain fma(a6,x6,fma(a4,x4,fma(a2,x2,a0*x0))), odd chain likewise, added
fn sgemv_n_g8(a0: f32, a1: f32, a2: f32, a3: f32, a4: f32, a5: f32, a6: f32, a7: f32, x: &[f32], o: usize) -> f32 {
    let e = np_fmaf(a6, x[o + 6], np_fmaf(a4, x[o + 4], np_fmaf(a2, x[o + 2], a0 * x[o])));
    let od = np_fmaf(a7, x[o + 7], np_fmaf(a5, x[o + 5], np_fmaf(a3, x[o + 3], a1 * x[o + 1])));
    e + od
}
// one row of sgemv_n (a is the column of values of that row over x): 8-x groups through the haswell
// 4x8/4x4 kernels, then 4-x, 2-x and 1-x tails; x stays under 4096 + the tail in this model's callers.
fn sgemv_n_row32(a: &[f32], x: &[f32]) -> f32 {
    let k = a.len();
    let mut y = 0.0f32;
    let mut i = 0;
    while i + 8 <= k {
        y += sgemv_n_g8(a[i], a[i + 1], a[i + 2], a[i + 3], a[i + 4], a[i + 5], a[i + 6], a[i + 7], x, i);
        i += 8;
    }
    if k - i >= 4 {
        y += np_fmaf(a[i + 2], x[i + 2], a[i] * x[i]) + np_fmaf(a[i + 3], x[i + 3], a[i + 1] * x[i + 1]);
        i += 4;
    }
    if k - i >= 2 {
        y += np_fmaf(a[i], x[i], a[i + 1] * x[i + 1]);
        i += 2;
    }
    if i < k {
        y += a[i] * x[i];
    }
    y
}
// vector @ matrix (sgemv_n): a is the C-ordered matrix viewed as column-major (m rows, k columns),
// x the vector. The SkylakeX small kernel (m <= 16384, k <= 48, k != 4) is a plain FMA chain over k
// with alpha folded in after (alpha = 1). Otherwise the haswell kernels; threads split rows (no sum
// change) or, for few rows and a long x, split x and add the parts in order.
fn np_sgemv_n(a: &[f32], m: usize, k: usize, x: &[f32], unit: bool) -> Vec<f32> {
    let mut y = vec![0.0f32; m];
    if m <= 16384 && k <= 48 && k != 4 {
        for r in 0..m {
            let mut s = 0.0f32;
            for c in 0..k {
                s = np_fmaf(a[r + c * m], x[c], s);
            }
            y[r] = s;
        }
        return y;
    }
    let nt = if m * k < 460800 { 1 } else { f32_ncpu() };
    // split the dot when the rows do not fill the threads (gemv_thread.c's split_x path)
    if nt > 1 && k > 9216 / m.max(1) && m * nt <= 1024 {
        for (c0, cn) in np_gemv_split(k, nt) {
            for r in 0..m {
                let mut s = 0.0f32;
                for c in c0..c0 + cn {
                    s = np_fmaf(a[r + c * m], x[c], s);
                }
                y[r] += s;
            }
        }
        return y;
    }
    let _ = unit;
    for r in 0..m {
        let mut col = vec![0.0f32; k];
        for c in 0..k {
            col[c] = a[r + c * m];
        }
        y[r] = sgemv_n_row32(&col, x);
    }
    y
}
// sgemm's direct kernel (sgemm_direct_skylakex.c): each element one FMA chain over all of k.
fn np_sgemm_direct(xv: &[f32], yv: &[f32], m: usize, k: usize, n: usize, xf: bool, yf: bool) -> Vec<f32> {
    let at = |r: usize, t: usize| if xf { xv[t * m + r] } else { xv[r * k + t] };
    let bt = |t: usize, c: usize| if yf { yv[c * k + t] } else { yv[t * n + c] };
    let mut out = vec![0.0f32; m * n];
    for r in 0..m {
        for c in 0..n {
            let mut s = 0.0f32;
            for t in 0..k {
                s = np_fmaf(at(r, t), bt(t, c), s);
            }
            out[r * n + c] = s;
        }
    }
    out
}
// the regular sgemm: k split into blocks of SGEMM_DEFAULT_Q (448; the last partial block's size is
// the same in level3.c and level3_thread.c), and each element of a block is one FMA chain over the
// block, added into C per block (the 16x4 SkylakeX kernel keeps one lane per element). Threads split
// rows and columns only, so the sums do not depend on the thread grid.
fn np_sgemm(xv: &[f32], yv: &[f32], m: usize, k: usize, n: usize, xf: bool, yf: bool) -> Vec<f32> {
    let q = 448usize;
    let mut out = vec![0.0f32; m * n];
    let at = |r: usize, t: usize| if xf { xv[t * m + r] } else { xv[r * k + t] };
    let bt = |t: usize, c: usize| if yf { yv[c * k + t] } else { yv[t * n + c] };
    let mnk = m as f64 * n as f64 * k as f64;
    let ncpu = f32_ncpu() as f64;
    let nthreads = if mnk <= 262144.0 {
        1
    } else if mnk / ncpu < 262144.0 {
        (mnk / 262144.0) as usize
    } else {
        ncpu as usize
    };
    let threaded = nthreads > 1 && !(n < 2 * 16 || (m < 2 * 16 && n < 16 * 1));
    let mut ls = 0;
    while ls < k {
        let mut ml = k - ls;
        if ml >= 2 * q {
            ml = q;
        } else if ml > q {
            ml = if threaded { ml.div_ceil(2) } else { (ml / 2).div_ceil(16) * 16 };
        }
        for r in 0..m {
            for c in 0..n {
                let mut s = 0.0f32;
                for t in ls..ls + ml {
                    s = np_fmaf(at(r, t), bt(t, c), s);
                }
                out[r * n + c] += s;
            }
        }
        ls += ml;
    }
    out
}
// numpy dot / matmul of two float32 arrays (1-d or 2-d): the float32 branch of np_dot2.
pub fn np_dot2_f32(x: &NdArr, y: &NdArr, matmul: bool) -> R {
    if !np_f32_simd() {
        return Err(np_unsup("float32 dot/matmul (OpenBLAS sgemm, AVX-512 only)"));
    }
    let d = np_promote(x.dt(), y.dt());
    if d != NT::F32 {
        return Err(np_unsup("float32 dot/matmul on other types"));
    }
    let (m, k) = if x.ndim() == 1 { (1, x.shape[0]) } else { (x.shape[0], x.shape[1]) };
    let (k2, n) = if y.ndim() == 1 { (y.shape[0], 1) } else { (y.shape[0], y.shape[1]) };
    if k != k2 {
        if matmul {
            return val_err(format!("matmul: Input operand 1 has a mismatch in its core dimension 0, with gufunc signature (n?,k),(k,m?)->(n?,m?) (size {k2} is different from {k})"));
        }
        return val_err(format!("shapes {} and {} not aligned: {} (dim {}) != {} (dim 0)", np_shape_repr(&x.shape), np_shape_repr(&y.shape), k, x.ndim() - 1, k2));
    }
    let mut shape = vec![];
    if x.ndim() == 2 {
        shape.push(m);
    }
    if y.ndim() == 2 {
        shape.push(n);
    }
    let out = if x.ndim() == 1 && y.ndim() == 1 {
        let (xv, yv) = (x.f32v(), y.f32v());
        let unit = x.st.first().is_none_or(|s| *s == 1) && y.st.first().is_none_or(|s| *s == 1);
        Buf::F32(vec![sdot32_1(&xv, &yv, unit)])
    } else {
        let (xv, yv) = (x.f32v(), y.f32v());
        let bl2 = |a: &NdArr| {
            let ok = |s0: isize, s1: isize, d1: usize| s1 == 1 && s0 >= d1 as isize;
            a.ndim() != 2 || ok(a.st[0], a.st[1], a.shape[1]) || ok(a.st[1], a.st[0], a.shape[0]) || a.shape.contains(&1)
        };
        let bl1 = |a: &NdArr| a.ndim() != 1 || a.st[0] >= 1 || a.shape[0] <= 1;
        let blas = !matmul || (bl2(x) && bl2(y) && bl1(x) && bl1(y));
        let ford = |a: &NdArr| a.ndim() == 2 && a.shape[0] > 1 && a.shape[1] > 1 && a.st[0] == 1;
        let vunit = |a: &NdArr| a.st.first().is_none_or(|s| *s == 1);
        let xvec = x.ndim() == 1 || m == 1;
        let yvec = y.ndim() == 1 || n == 1;
        let xunit = if x.ndim() == 1 { vunit(x) } else { k <= 1 || x.st[1] == 1 };
        let yunit = if y.ndim() == 1 { vunit(y) } else { k <= 1 || y.st[0] == 1 };
        if blas && !xvec && yvec && k > 0 {
            // matrix @ vector
            Buf::F32(if ford(x) {
                let mut cm = vec![0.0f32; m * k];
                for i in 0..m {
                    for t in 0..k {
                        cm[i + t * m] = xv[i * k + t];
                    }
                }
                np_sgemv_n(&cm, m, k, &yv, yunit)
            } else if x.st[0] == k as isize && x.st[1] == 1 && k <= 8 {
                np_sgemv_t_small(&xv, m, k, &yv)
            } else {
                np_sgemv_t(&xv, m, k, &yv)
            })
        } else if blas && xvec && !yvec && k > 0 {
            // vector @ matrix: y is k x n, column-major n x k when C-ordered
            Buf::F32(if ford(y) {
                let mut rm = vec![0.0f32; n * k];
                for t in 0..k {
                    for j in 0..n {
                        rm[j * k + t] = yv[t * n + j];
                    }
                }
                np_sgemv_t(&rm, n, k, &xv)
            } else {
                np_sgemv_n(&yv, n, k, &xv, xunit)
            })
        } else if xvec && yvec && blas && k > 0 {
            let mut o = vec![0.0f32; m * n];
            let mut col = vec![0.0f32; k];
            for j in 0..n {
                for t in 0..k {
                    col[t] = yv[t * n + j];
                }
                for i in 0..m {
                    o[i * n + j] = sdot32_1(&xv[i * k..(i + 1) * k], &col, xunit && yunit);
                }
            }
            Buf::F32(o)
        } else if x.ndim() == 2 && y.ndim() == 2 && m > 1 && n > 1 && k > 0 {
            let tr = |a: &NdArr| {
                if !matmul {
                    a.st[0] == 1 && a.st[1] == a.shape[0] as isize
                } else if bl2(a) {
                    !(a.st[1] == 1 && a.st[0] >= a.shape[1] as isize)
                } else {
                    a.st[0].abs() < a.st[1].abs()
                }
            };
            let (xf, yf) = (tr(x), tr(y));
            let mnk = m as f64 * n as f64 * k as f64;
            // sgemm_direct_performant: under 28*512*512 multiplies, B columns a multiple of 4 below
            // 8*512*512, and no multithreading above 2*350*512
            let direct = !xf && !yf && mnk < 28.0 * 512.0 * 512.0 && (n % 4 == 0 || mnk < 8.0 * 512.0 * 512.0) && !(mnk > 2.0 * 350.0 * 512.0 && f32_ncpu() > 1);
            if direct {
                Buf::F32(np_sgemm_direct(&xv, &yv, m, k, n, xf, yf))
            } else if mnk <= 1e6 && !(yf && !xf && (m * n > 1200 || k < 32)) {
                Buf::F32(np_sgemm_small(&xv, &yv, m, k, n, xf, yf))
            } else {
                Buf::F32(np_sgemm(&xv, &yv, m, k, n, xf, yf))
            }
        } else {
            let mut o = vec![0.0f32; m * n];
            let mut col = vec![0.0f32; k];
            for j in 0..n {
                for t in 0..k {
                    col[t] = yv[t * n + j];
                }
                for i in 0..m {
                    let mut acc = 0.0f32;
                    for t in 0..k {
                        acc += xv[i * k + t] * col[t];
                    }
                    o[i * n + j] = acc;
                }
            }
            Buf::F32(o)
        }
    };
    Ok(np_out(out, shape))
}
// sgemm's small kernels (sgemm_small_kernel_*_skylakex.c): per element one FMA chain over k for
// M-chunks of 16 and more, and for the last 1..8 rows with k >= 32 a 16-lane dot whose lanes hold
// k mod 16, reduced in the kernel's tree (REDUCE_4 for rows in a 4-group or columns in a 4-group,
// the compiler's _mm512_reduce_add_ps tree otherwise). a/b give the operands of the column-major
// product the kernel sees; here they are handed the transposed flags like the regular path.
fn np_sgemm_small(xv: &[f32], yv: &[f32], m: usize, k: usize, n: usize, xf: bool, yf: bool) -> Vec<f32> {
    let at = |r: usize, t: usize| if xf { xv[t * m + r] } else { xv[r * k + t] };
    let bt = |t: usize, c: usize| if yf { yv[c * k + t] } else { yv[t * n + c] };
    let mut out = vec![0.0f32; m * n];
    for r in 0..m {
        for c in 0..n {
            // the kernel's M is the column index here (numpy's column), N the row
            let mm = n - c;
            let (group4, group2) = (mm >= 4, mm == 2);
            let mut s;
            if mm > 8 || k < 32 {
                let mut acc = 0.0f32;
                for t in 0..k {
                    acc = np_fmaf(at(r, t), bt(t, c), acc);
                }
                s = acc;
            } else {
                // 16-lane dot over k mod 16, lanes as FMA chains over the 16-strided values
                let k16 = k & !15;
                let rem = k - k16;
                let mut lane = [0.0f32; 16];
                let mut t = 0;
                while t < k16 {
                    for l in 0..16 {
                        lane[l] = np_fmaf(at(r, t + l), bt(t + l, c), lane[l]);
                    }
                    t += 16;
                }
                if rem > 0 {
                    for l in 0..rem {
                        lane[l] = np_fmaf(at(r, k16 + l), bt(k16 + l, c), lane[l]);
                    }
                }
                s = if group4 || (group2 && mm <= 8 && c % 4 == 0 && n - c >= 4) {
                    // REDUCE_4's tree: four 4-lane groups (l+l+1)+(l+2+l+3), then (g0+g1)+(g2+g3)
                    let g = |q: usize| (lane[4 * q] + lane[4 * q + 1]) + (lane[4 * q + 2] + lane[4 * q + 3]);
                    (g(0) + g(1)) + (g(2) + g(3))
                } else {
                    // gcc's _mm512_reduce_add_ps: ((W0+W8)+(W4+W12)) + ((W1+W9)+(W5+W13))
                    // + ((W2+W10)+(W6+W14)) + ((W3+W11)+(W7+W15))
                    let a0 = (lane[0] + lane[8]) + (lane[4] + lane[12]);
                    let a1 = (lane[1] + lane[9]) + (lane[5] + lane[13]);
                    let a2 = (lane[2] + lane[10]) + (lane[6] + lane[14]);
                    let a3 = (lane[3] + lane[11]) + (lane[7] + lane[15]);
                    (a0 + a1) + (a2 + a3)
                };
            }
            out[r * n + c] = s;
        }
    }
    out
}
