    let a = |c: usize, t: usize| if yf { yv[c * k + t] } else { yv[t * n + c] };
    let b = |r: usize, t: usize| if xf { xv[t * m + r] } else { xv[r * k + t] };
    let m16 = n & !15;
    let m4 = n & !3;
    let m2 = n & !1;
    let n4 = m & !3;
    let n2 = m & !1;
