import numpy as np, ctypes
libm = ctypes.CDLL('libm.so.6'); libm.fmaf.restype=ctypes.c_float; libm.fmaf.argtypes=[ctypes.c_float,ctypes.c_float,ctypes.c_float]
def fm(x, y, z):
    return libm.fmaf(x, y, z)
def fa(x, y):
    return np.float32(np.float32(x)+np.float32(y))
def lanes_for(r, c):
    lanes = [np.float32(0.0)] * 16
    k16 = 5000 & ~15
    rem = 5000 - k16
    t = 0
    while t < k16:
        for l in range(16):
            lanes[l] = fm(np.float32(a[r][t+l]), np.float32(b[t+l][c]), lanes[l])
        t += 16
    for l in range(rem):
        lanes[l] = fm(np.float32(a[r][k16+l]), np.float32(b[k16+l][c]), lanes[l])
    return lanes
r, c, s2 = 3, 5000, 0.1
a = (np.sin(np.arange(r*c)*0.37+s2)*3.0).reshape(r, c).astype(np.float32)
b = (np.sin(np.arange(c*3)*0.37+0.7)*3.0).reshape(c, 3).astype(np.float32)
want = (a@b)
def qtree(lanes):
    q = [fa(fa(lanes[4*i],lanes[4*i+2]),fa(lanes[4*i+1],lanes[4*i+3])) for i in range(4)]
    return fa(fa(q[0],q[1]),fa(q[2],q[3]))
def dtree(lanes):
    g = [fa(fa(lanes[4*i],lanes[4*i+1]),fa(lanes[4*i+2],lanes[4*i+3])) for i in range(4)]
    return fa(fa(g[0],g[1]),fa(g[2],g[3]))
def atree(lanes):
    p0 = fa(fa(lanes[0],lanes[8]), fa(lanes[4],lanes[12]))
    p1 = fa(fa(lanes[1],lanes[9]), fa(lanes[5],lanes[13]))
    p2 = fa(fa(lanes[2],lanes[10]), fa(lanes[6],lanes[14]))
    p3 = fa(fa(lanes[3],lanes[11]), fa(lanes[7],lanes[15]))
    return fa(fa(p0,p1), fa(p2,p3))
for (rr, cc) in [(0,0),(0,1),(0,2),(1,0),(1,1),(2,2)]:
