            let unpacklo = |a: &[f32; 8], b: &[f32; 8], out: &mut [f32; 8]| {
                out[0] = a[0];
                out[1] = b[0];
                out[2] = a[1];
                out[3] = b[1];
                out[4] = a[4];
                out[5] = b[4];
                out[6] = a[5];
                out[7] = b[5];
            };
            let unpackhi = |a: &[f32; 8], b: &[f32; 8], out: &mut [f32; 8]| {
                out[0] = a[2];
                out[1] = b[2];
                out[2] = a[3];
                out[3] = b[3];
                out[4] = a[6];
                out[5] = b[6];
                out[6] = a[7];
                out[7] = b[7];
            };
