                out[0] = a[0];
                out[1] = a[1];
                out[2] = b[0];
                out[3] = b[1];
                out[4] = a[4];
                out[5] = a[5];
                out[6] = b[4];
                out[7] = b[5];
            };
            let shee = |a: &[f32; 8], b: &[f32; 8], out: &mut [f32; 8]| {
                out[0] = a[2];
                out[1] = a[3];
                out[2] = b[2];
                out[3] = b[3];
                out[4] = a[6];
                out[5] = a[7];
